    m = index["matrix"]
    n = m.shape[0]
    v = np.zeros(m.shape[1])
    for t in _tokens(query):
        if t in index["pos"]:
            v[index["pos"][t]] += 1.0
    total = v.sum()
    if total > 0:
        nz = v > 0
        df = (m[:, nz] > 0).sum(axis=0)
        v[nz] = (v[nz] / total) * (np.log((n + 1.0) / (df + 1.0)) + 1.0)
    norms = np.linalg.norm(m, axis=1) * np.linalg.norm(v)
    norms[norms == 0.0] = 1.0
    scores = (m @ v) / norms
    return sorted(range(n), key=lambda i: (-scores[i], i))

def evaluate(index, queries, relevant_sets, k):
    recalls = []
    rrs = []
    for query, relevant in zip(queries, relevant_sets):
        rel = set(relevant)
        order = rank_query(index, query)
        recalls.append(len(set(order[:k]) & rel) / len(rel))
        rr = 0.0
        for position, doc in enumerate(order, start=1):
            if doc in rel:
                rr = 1.0 / position
                break
        rrs.append(rr)
    return {"recall_at_k": sum(recalls) / len(recalls), "mrr": sum(rrs) / len(rrs)}

